options=read('/input/options')
result=[]
for c in combinations(options,3):
  sel=list(c)
  sel_ids=[x['id'] for x in sel]
  workers=[x['worker'] for x in sel]
  jobs=[x['job'] for x in sel]
  unique_workers=True
  unique_jobs=True
  job_set=[]
  for w in workers:
    if w in job_set:
      unique_workers=False
      break
    job_set=job_set+[w]
  if not unique_workers: continue
  job_set=[]
  for j in jobs:
    if j in job_set:
      unique_jobs=False
      break
    job_set=job_set+[j]
  if not unique_jobs: continue
  # Check coverage
  cover_jobs=['j0','j1','j2']
  cover_ok=True
  for cj in cover_jobs:
    found=False
    for j in jobs:
      if j==cj:
        found=True
        break
    if not found:
      cover_ok=False
      break
  if not cover_ok: continue
  # Check closed dependencies
  closed=True
  for x in sel:
    for r in x['requires']:
      found_r=False
      for y in sel:
        if y['id']==r:
          found_r=True
          break
      if not found_r:
        closed=False
        break
    if not closed:
      break
  if not closed: continue
  # Check conflicts
  conflict=False
  for i in range(3):
    for j in range(i+1,3):
      c1=sel[i]['conflicts']
      c2=sel[j]['conflicts']
      id1=sel[i]['id']
      id2=sel[j]['id']
      found_conflict=False
      for c_id in c1:
        if c_id==id2:
          found_conflict=True
          break
      if found_conflict:
        conflict=True
        break
      for c_id in c2:
        if c_id==id1:
          found_conflict=True
          break
      if found_conflict:
        conflict=True
        break
    if conflict:
      break
  if conflict: continue
  if len(sel)!=3: continue
  result=sel_ids
  break
